import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第十五卦 谦 地山谦 坤上艮下","description":"周易 - 第十五卦 谦 地山谦 坤上艮下","frontmatter":{"title":"第十五卦 谦 地山谦 坤上艮下","description":"周易 - 第十五卦 谦 地山谦 坤上艮下"},"headers":[],"relativePath":"zh/classics/zhouyi/016.md","filePath":"zh/classics/zhouyi/016.md"}'),l={name:"zh/classics/zhouyi/016.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="谦" tabindex="-1">谦 <a class="header-anchor" href="#谦" aria-label="Permalink to “谦”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨，君子有终。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>谦，亨，天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可踰，君子之终也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>地中有山，谦；君子以裒多益寡，称物平施。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>谦谦君子，用涉大川，吉。 象曰：谦谦君子，卑以自牧也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>鸣谦，贞吉。象曰：鸣谦贞吉，中心得也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>劳谦君子，有终吉。象曰：劳谦君子，万民服也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>无不利，(扌为)谦。象曰：无不利，(扌为)谦；不违则也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>不富，以其邻，利用侵伐，无不利。象曰：利用侵伐，征不服也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>鸣谦，利用行师，征邑国。象曰：鸣谦，志未得也。可用行师，征邑国也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
